import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, step } from '../game/neon.js';

test('ball should not tunnel through brick at high speed', (t) => {
  const state = createState(6); // Level 6 for high speed
  const brick = state.bricks[0];

  // Position ball so that it is completely ABOVE in frame N and completely BELOW in frame N+1.
  // Above: ball.y + ball.r < brick.y  =>  ball.y + 7 < 48  =>  ball.y < 41.
  // Below: ball.y - ball.r > brick.y + brick.h  =>  ball.y - 7 > 68  =>  ball.y > 75.

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = 40;
  state.ball.vy = 710; // Speed for level 6

  const dt = 0.05;
  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {}
  };

  step(state, dt);
  frame(ctx, state);

  assert.notStrictEqual(state.ball.vy, 710, 'Ball should have bounced and changed vy');
});

